function projectCard(p,i,actual=false){return `<article class="project-card" data-project="${i}"><button class="cardmore" data-action="project-more" data-index="${i}" aria-label="${esc(p[0])}更多">•••</button><div class="project-top">${!actual&&i<9?`<img class="tile" src="${img('picon'+i)}" alt="">`:tile(p[4],p[5])}<div class="project-name"><h3>${esc(p[0])}</h3>${badge(p[15]?({active:'运行中',planned:'规划中',internal:'内网',offline:'已下线'}[p[15]]||p[15]):p[14]?'规划中':'运行中',p[14]?'planned':['internal','offline'].includes(p[15])?'gray':'')}<div class="project-domain">${esc(p[1]||'')}</div></div></div><div class="project-copy"><p>${esc(p[2])}</p>${tags(p[3],p[5]==='purple'?'purple':p[5]==='orange'&&i===2?'green':'')}</div>${p[6]?`<img class="project-shot" src="${img(p[6])}" alt="${esc(p[0])}预览">`:''}<div class="project-meta"><span>${ico('file-text')}${p[7]}</span><span>${ico('people')}${p[8]}</span><span>${ico('eye')}${p[9]}</span><span>${ico('calendar')}${p[10]}</span></div><div class="project-actions">${p[12]?linkbtn('打开',p[12],'blue'):btn('查看','project-detail','blue')}${btn(p[11],p[11]==='编辑'?'edit-project':'project-detail')}${i===2?btn('部署','pending','','shield'):i===5?btn('启动部署','pending','','shield'):btn('编辑','edit-project','','pencil')}${btn('•••','project-more','more')}</div></article>`}
function getProjectRows(){if(mode==='actual')return actualItems.filter(x=>x.category==='site').map(x=>[x.name,x.url?.replace(/^https?:\/\//,''),x.note||'暂无项目说明',x.stack?[x.stack]:['项目'],'globe','','','—','—','—',x.updatedAt?.slice(5,10)??'—','详情',x.url,x.id,x.status==='planned',x.status]);return [...projects,...demoDrafts.filter(x=>x.type==='projects').map(x=>[x.name,'',x.note,['项目'],'globe','','','0','0','0','10-22','详情','',null,true])]}
function projectGrid(){const rows=getProjectRows().map((p,i)=>({p,i})).filter(({p})=>(!query||p.join(' ').toLowerCase().includes(query.toLowerCase()))&&(!filter||(filter===1?(mode==='actual'?p[15]==='active':!p[14]):filter===2?!!p[14]:mode==='actual'&&p[15]==='offline')));return rows.length?rows.map(({p,i})=>projectCard(p,i,mode==='actual')).join(''):'<div class="empty-state">没有符合条件的项目</div>'}
