function allIdeas(){return mode==='actual'?actualItems.filter(x=>x.category==='idea').map(x=>[x.name,x.note||'暂无说明','产品想法',x.stack||'灵感','',x.updatedAt?.slice(0,10)||'',null,x.id]):[...ideaDefs,...demoDrafts.filter(x=>x.type==='ideas').map(x=>[x.name,x.note,'产品想法','灵感','','刚刚',null])]}
function ideaGrid(){const type=['全部','产品想法','技术方案','行业洞察','生活记录','待整理'][filter];const rows=allIdeas().map((d,i)=>({d,i})).filter(({d})=>(!filter||d[2]===type)&&(!query||d.join(' ').toLowerCase().includes(query.toLowerCase())));return rows.length?rows.map(({d,i})=>`<article class="idea-card" tabindex="0" role="button" data-idea="${i}">${i<12&&mode==='demo'?`<img class="idea-cover" src="${img('idea'+i)}" alt="${esc(d[0])}封面">`:''}<div class="idea-body"><h3>${esc(d[0])}</h3><p>${esc(d[1])}</p><div class="tags">${tag(d[2],d[2]==='生活记录'?'orange':d[2]==='行业洞察'?'green':'purple')}${tag(d[3])}${d[4]?tag(d[4]):''}</div><div class="idea-date"><span>${esc(d[5])}</span><span>•••</span></div></div></article>`).join(''):'<div class="empty-state">没有符合条件的灵感</div>'}
function tagcloud(data){return `<div class="tagcloud">${data.map(([s,n])=>`<button class="tag" data-tag="${esc(s)}">${esc(s)} <b>${n}</b></button>`).join('')}</div>`}
function ideasPage(){return header('灵感','把一闪而过的想法记录下来，让灵感不再流失。',btn('新增灵感　⌄','new-idea','primary','plus'),'bulb')+`<div class="split"><div><div class="toolbar" style="margin:0"><div style="flex:1;min-width:0">${tabs(['全部 (32)','产品想法 (12)','技术方案 (8)','行业洞察 (5)','生活记录 (7)','待整理 (0)'],'idea-filter',filter)}</div><div class="seg">${btn('卡片视图','view-cards',display==='cards'?'active':'','layout-grid')}${btn('列表视图','view-list',display==='list'?'active':'','list')}${btn('看板视图','view-board',display==='board'?'active':'','layout-grid')}</div></div><div class="toolbar">${search('搜索灵感内容…','ideaSearch')}${select(['全部标签','AI','Agent','技术','生活'],'ideaTag')}${select(['全部类型','产品想法','技术方案','行业洞察','生活记录'],'ideaType')}${select(['最新创建','最早创建'],'ideaSort')}</div><div class="ideas-grid ${display==='list'?'list-mode':display==='board'?'board-mode':''}" id="ideaGrid">${ideaGrid()}</div></div><aside class="stack">${panel('灵感统计',`<div class="mini-stats">${[['32','总灵感数','bulb','orange','↑ 28%'],['12','产品想法','file-text','purple','↑ 33%'],['8','技术方案','terminal','','↑ 14%'],['5','行业洞察','trending','orange','↑ 25%']].map(d=>`<div class="mini-stat">${tile(d[2],d[3])}<div><strong>${mode==='demo'?d[0]:'—'}</strong><p>${d[1]}</p><small>${mode==='demo'?d[4]:'待统计'}</small></div></div>`).join('')}</div>`,select(['本月','本周','全部']))}${panel('热门标签',tagcloud([['AI',12],['Agent',8],['产品',8],['技术',6],['效率',6],['生活',5],['SaaS',4],['加密',4],['工具',4],['海外',4],['自媒体',3],['健康',3],['投资',3],['出行',3],['UI',3],['其他',6]]),actionLink('全部标签','tags'))}${panel('快速记录灵感',`<textarea class="quick-note" id="quickNote" placeholder="记录你的灵感…\n支持上传图片、链接，或让 AI 帮你整理想法"></textarea><div class="quick-footer">${ico('image')}${ico('link')}${ico('file-text')} #<span class="push"></span>${select(['公开','私有'])}${btn('保存','quick-save','primary small')}</div>`,btn('◉ AI 辅助','pending','small'))}${panel('灵感收集箱',`<p class="ui-note">从其他平台快速收集灵感</p><div class="collection-buttons">${['网页剪藏','截图识别','API 收集','稍后阅读'].map(t=>btn(t,'pending','small','file-text')).join('')}</div>`)}</aside></div>`}
function ring(total,label,kind='memory',legend=true){const list=kind==='content'?[['文章','42.3%　511'],['视频','18.4%　222'],['帖子','16.7%　201'],['新闻','12.1%　146'],['图像','6.8%　82'],['其他','3.7%　44']]:kind==='security'?[['登录安全','正常'],['凭据加密','正常'],['访问控制','正常'],['系统防护','正常']]:kind==='tools'?[['运行中','20'],['异常','1'],['已停止','1'],['未配置','2']]:[['深度观察','3,582 (42.5%)'],['经历事件','1,874 (22.2%)'],['客观事实','1,206 (14.3%)'],['项目相关','892 (10.6%)'],['灵感想法','624 (7.4%)'],['其他','246 (2.9%)']];const colors=kind==='content'?['#4b79ff','#28cdb1','#ffb347','#ff9828','#bd8df6','#8a99b6']:kind==='tools'?['#00c08a','#fa5774','#aab1c2','#c5cbd8']:['#07998c','#12bdb8','#25b5d9','#7050ed','#a06beb','#8a8da4'];return `<div class="ring-wrap"><div class="ring" ${kind==='security'?'style="background:conic-gradient(#00bd83 0 100%)"':kind==='tools'?'style="background:conic-gradient(#00c08b 0 84%,#fc6271 84% 88%,#b3bac9 88% 92%,#d4d9e3 92%)"':''}><div class="ring-text"><strong>${total}</strong><small>${label}</small></div></div>${legend?`<div class="ring-legend">${list.map(([s,n],i)=>`<div><i style="background:${kind==='security'?'#00bd83':colors[i]}"></i><span>${s}</span><b>${n}</b></div>`).join('')}</div>`:''}</div>`}
function graph(){const nodes=[['AI',11,20],['AI',33,1],['项目',56,0],['加密',82,16],['钍斑',86,59],['核密',62,82],['加密',25,87],['工具',4,61]];return `<div class="graph"><svg viewBox="0 0 340 180">${nodes.map(([,x,y],i)=>`<path d="M170 90L${x*3.1+24} ${y*1.5+20}" stroke="#dfebf9"/><circle cx="${(x*3.1+24+170)/2}" cy="${(y*1.5+20+90)/2}" r="3" fill="${['#1ea9c1','#ffaa3e','#32afc1','#d07b75'][i%4]}"/>`).join('')}</svg>${nodes.map(([s,x,y],i)=>`<span class="graph-node" style="left:${x}%;top:${y}%;background:${['#e4f6fc','#fff1df','#e2f7f0','#ffeaed'][i%4]}">${s}</span>`).join('')}<span class="graph-node center">demo</span></div>`}
function getMemories(){return mode==='demo'?memories:actualMemories.map(m=>[new Date(m.mentioned_at||m.date||Date.now()).toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit'}),m.text?.slice(0,45)||'记忆条目',m.text||'',m.fact_type||m.type||'记忆',['来源记忆'],'',m.id])}
function memoryRows(){const rows=getMemories().map((m,i)=>({m,i})).filter(({m})=>(!query||m.join(' ').toLowerCase().includes(query.toLowerCase()))&&(!memFilter||(memFilter===1?m[3]==='对话':memFilter===2?m[3]==='网页':memFilter===3?m[3]==='文档':m[4].includes('灵感'))));return rows.length?rows.map(({m,i},j)=>`${j===0?'<h3 class="day">今天 <span style="color:#7b8aab;font-weight:500">10月22日</span></h3>':i===5?'<h3 class="day">10月21日</h3>':''}<article class="timeline-row ${selectedMemory===i?'active':''}" role="button" tabindex="0" data-memory="${i}"><span class="timeline-time">${esc(m[0])}</span>${m[5]?`<img class="timeline-thumb" src="${img(m[5])}" alt="">`:tile('file-text')}<div class="timeline-copy"><h4>${esc(m[1])}</h4><p>${esc(m[2])}</p>${tags(m[4])}</div><span class="tiny-label">${esc(m[3])}</span>${rowMore()}</article>`).join(''):'<div class="empty-state">没有匹配的记忆</div>'}
function memoryDetail(){const m=getMemories()[selectedMemory];if(!m)return '<div class="empty-state">选择一条记忆查看详情</div>';return `${m[5]?`<div style="position:relative"><img class="detail-image" src="${img(m[5])}" alt="${esc(m[1])}"><button class="btn small" data-action="close-detail" style="position:absolute;right:10px;top:10px;padding:0 8px" aria-label="关闭详情">×</button></div>`:''}<div class="detail-body"><h3>${esc(m[1])}</h3><div class="detail-meta">${ico('clock')}2026-10-22 ${esc(m[0])}　◇ 工具　♧ 共 3 条关联</div><h4>内容摘要</h4><p>${esc(m[2])}</p><h4>标签</h4>${tags(m[4])}<h4>关联内容 (3)</h4>${[['远程连接配置示例','对话 · 10-22 21:10'],['设备兼容性示例','网页 · 10-22 20:48'],['协作方案对比示例','对话 · 10-21 16:30']].map(([s,d],i)=>`<div class="related">${tile(i===1?'home':'file-text',i===1?'orange':'')}<div><strong>${s}</strong><small>${d}</small></div></div>`).join('')}<h4>原始链接</h4><a class="detail-link" href="https://example.com/docs/" target="_blank" rel="noopener">${ico('link')}　https://example.com/docs/　↗</a></div><div class="detail-footer">${btn('编辑','edit-memory','','pencil')}${btn('复制内容','copy-memory','','copy')}${btn('删除','delete-memory','danger','trash')}</div>`}
function memoryPage(){return header('记忆系统','把 Hindsight 挂载到你的 AI 客户端，让它自动读写长期记忆。',btn('使用指南','guide','','book')+btn('设置','memory-settings','','settings')+btn('新增记忆 ⌄','new-memory','primary','plus'))+`<div class="kpis">${[['8,424','总记忆条数','file-text','purple','↑ 12%'],['140,923','关联链接','link','green','↑ 8%'],['1,809','归档文档','file-text','','↑ 5%'],['3,582','深度观察','pie','','↑ 18%']].map((s,i)=>stat(mode==='demo'?s[0]:[actualStats?.total_nodes,actualStats?.total_links,actualStats?.total_documents,actualStats?.nodes_by_fact_type?.observation][i]?.toLocaleString()??'—',s[1],s[2],s[3],mode==='demo'?s[4]:'实际记录',i)).join('')}</div><div class="memory-layout ${!detailOpen?'full-detail-hidden':''}"><aside class="stack">${panel('记忆分类',ring(mode==='demo'?'8,424':actualStats?.total_nodes?.toLocaleString()??'—','总记忆'))}${panel('标签云',tagcloud([['AI','1.2K'],['创业',892],['技术',764],['生活',439],['产品',420],['加密',398],['读书',321],['健康',318],['工具',274],['面试',231],['海外',209],['投资',187],['销售',166],['模型',154],['网络',132],['其他',320]]),actionLink('全部标签 (128)','tags'))}${panel('知识图谱',graph(),actionLink('查看完整图谱','graph'))}</aside><section class="panel memory-stream">${tabs(['全部记忆 (8,424)','对话记录 (3,428)','网页采集 (1,206)','归档文档 (892)','灵感想法 (624)'],'memory-filter',memFilter)}<div class="toolbar">${search('搜索记忆内容…','memorySearch')}${select(['时间','今天','近7天'])}${select(['标签','工具','AI'])}${select(['项目','工作台','个人'])}${select(['类型','网页','对话'])}</div><div id="memoryRows">${memoryRows()}</div></section>${detailOpen?`<aside class="panel memory-detail" id="memoryDetail">${memoryDetail()}</aside>`:''}</div>`}
const sources=[['𝕏','X (Twitter)','社交媒体','每 30 分钟','10-22 20:45','black'],['▶','YouTube','视频平台','每 1 小时','10-22 19:32','red'],['知','知乎','问答社区','每 2 小时','10-22 18:21',''],['☏','公众号','内容平台','每 1 小时','10-22 20:12','green'],['●','Reddit','社区论坛','每 1 小时','10-22 17:55','red'],['◔','RSS 订阅','新闻资讯','每 30 分钟','10-22 20:30','orange']];
const tasks=[['𝕏','X 热点话题采集','采集 AI、科技相关话题','320 / 500',64,'运行中','black','剩余 12 分钟'],['▶','YouTube 视频分析','AI 技术与产品相关视频','18 / 20',90,'运行中','red','剩余 8 分钟'],['▣','行业新闻聚合','36 氪、虎嗅等科技媒体','120 / 120',100,'已完成','','10-22 19:20'],['▧','论文摘要采集','arXiv / HuggingFace','45 / 100',45,'运行中','purple','剩余 25 分钟'],['♧','竞品动态追踪','OpenAI / Anthropic 等','0 / 50',0,'等待中','black','预计 21:00'],['●','Reddit 讨论采集','r/LocalLLaMA 等子版块','200 / 200',100,'已完成','red','10-22 18:10']];
function bars(){return `<div class="bar-chart">${[0,1,2,3,4,5,6].map((n)=>`<div class="bars">${[1,2,3,4,5].map((x)=>`<i style="height:${20+((n*31+x*17)%100)}px"></i>`).join('')}<label>10/${16+n}</label></div>`).join('')}</div>`}
function logs(kind='intel'){const l=kind==='intel'?['开始采集 X 热点话题…','获取到 32 条新内容','内容去重完成，新增 28 条','正在进行文本清洗…','生成摘要与标签…','写入向量数据库 (28/28)','采集任务执行完成','YouTube 视频进行中…','处理视频转录文本 (3/5)…','有 3 个视频转录超时，重试中…','重试成功']:['nginx: 200 GET /api/health 12ms','magpie: model request success','fail2ban: blocked 1 IP (198.51.100.50)','x-ui: new connection from 198.51.100.60','cron: backup completed in 32s','redis: RDB saved (12.6 MB)','token-mail: SMTP connection failed','system: load average: 0.42, 0.36, 0.28','docker: container magpie restarted','nginx: 200 POST /api/chat 356ms'];return `<div class="log-console">${l.map((s,i)=>`<div>20:56:${String(12+i*2).padStart(2,'0')} <span class="${i===9?'warn':i===6&&kind!=='intel'?'error':''}">[${i===9?'WARN':i===6&&kind!=='intel'?'ERROR':'INFO'}]</span> ${s}</div>`).join('')}</div>`}
function sourceTable(){const rows=sources.filter(s=>!query||s.join(' ').toLowerCase().includes(query.toLowerCase())).map(s=>[`<input type="checkbox" aria-label="选择${esc(s[1])}">`,`<div class="logo-cell">${logo(s[0],s[5])}${s[1]}</div>`,s[2],s[3],s[4],badge(),rowMore()]);return table(['□','采集源 ⌄','类型','更新频率','最近更新','状态','操作'],rows)}
function taskList(){return tasks.map((s,i)=>`<div class="task" data-task="${i}">${logo(s[0],s[6])}<div class="task-copy"><strong>${s[1]}</strong><small>${s[2]}</small></div><div class="task-progress">${s[3]}<div class="progress"><i style="width:${s[4]}%;${s[4]===100?'background:#00bd83':''}"></i></div>${s[4]}%</div><div class="task-state">${badge(s[5],s[5]==='等待中'?'orange':s[5]==='已完成'?'gray':'')}<small>◷ ${s[7]}</small></div>${rowMore()}</div>`).join('')}
function intelPage(){const tabsHTML=tabs(['概览','采集源','采集任务','处理流水线','数据集','入库记录','设置'].map((s,i)=>ico(['layout-grid','git-branch','list-checks','radar','server','file-text','settings'][i])+s),'intel-tabs');return header('信息采集','基于 aihot 的热点情报中枢，支持多源采集、自动处理与知识入库。',btn('使用指南','guide','','book')+btn('新建采集任务　⌄','new-task','primary','plus'))+tabsHTML+`<div class="kpis">${stat('1,206','本月采集内容','file-text','','↑ 32%',0)}${stat('18','采集源数量','link','green','↑ 12%',1)}${stat('4','运行中任务','container','purple','-- 0%',2)}${stat('892','已入库内容','container','orange','↑ 28%',3)}</div><div class="intel-grid"><div class="stack">${panel('采集源管理 (18)',`<div class="subtabs">${['◆ 全部 18','◆ 运行中 12','● 已暂停 3','● 已停止 3'].map((s,i)=>`<button class="subtab ${i===0?'active':i===1?'green':''}" data-local-filter="${i}">${s}</button>`).join('')}</div><div class="toolbar">${search('搜索采集源…','sourceSearch')}${select(['全部类型','社交媒体','视频平台','新闻资讯'],'sourceType')}</div><div id="sourceTable">${sourceTable()}</div>`,btn('新增采集源','new-source','primary small','plus'),'管理所有数据源，支持定时/实时采集')}${panel('采集数据概览',bars(),'<span style="color:#8b99b6;font-size:9px">▪ 社交媒体　▪ 新闻资讯　▪ 视频平台　▪ 问答社区</span>','近 7 天采集内容统计')}</div><div class="stack">${panel('采集任务 (6)',`<div class="subtabs">${['◆ 全部 6','◆ 运行中 4','● 已完成 12','♦ 失败 1'].map((s,i)=>`<button class="subtab ${i===0?'active':i===1?'green':''}" data-task-filter="${i}">${s}</button>`).join('')}</div><div id="tasksList">${taskList()}</div>`,actionLink('查看全部','tasks')+btn('新建任务','new-task','primary small','plus'),'管理采集任务的执行状态和历史记录')}${panel('内容类型分布',ring('1,206','总采集数','content'),select(['本月','本周']))}</div><div class="stack">${panel('处理流水线',[['数据采集','多源并发采集、去重过滤','globe','green'],['内容清洗','去噪、格式化、语言检测','file-text','purple'],['内容处理','摘要、分类、打标签','container','orange'],['入库与分发','写入记忆系统 / 向量化','container','']].map((s,i)=>`<div class="pipeline-step">${tile(s[2],s[3])}<div><strong>${i+1}. ${s[0]}</strong><small>${s[1]}</small></div>${badge()}</div>${i<3?'<div class="flow-arrow">↓</div>':''}`).join(''),actionLink('查看详情','pipeline'))}${panel('实时运行日志',logs(),actionLink('全部日志','logs'))}</div></div>`}
function monitorChart(){return `<svg class="monitor-chart" viewBox="0 0 400 180" preserveAspectRatio="none" aria-label="最近24小时CPU、内存、磁盘演示曲线">${[10,45,80,115,150].map((y,i)=>`<path d="M30 ${y}H398" stroke="#e6eefb" stroke-dasharray="2 2"/><text x="0" y="${y+4}" fill="#8c9abc" font-size="10">${100-i*25}%</text>`).join('')}${['#407dff','#ffa046','#37c7c9'].map((c,j)=>`<path d="M30 150 ${Array.from({length:35},(_,i)=>`L${30+i*10.8} ${[106,62,126][j]+Math.sin(i*1.6+j)*9+Math.cos(i*.6)*7}`).join(' ')}L398 150Z" fill="${c}" fill-opacity=".04"/><path d="${Array.from({length:35},(_,i)=>`${i?'L':'M'}${30+i*10.8} ${[106,62,126][j]+Math.sin(i*1.6+j)*9+Math.cos(i*.6)*7}`).join(' ')}" fill="none" stroke="${c}" stroke-width="1.2"/>`).join('')}${['00:00','04:00','08:00','12:00','16:00','20:00'].map((t,i)=>`<text x="${30+i*65}" y="175" fill="#8190b2" font-size="10">${t}</text>`).join('')}</svg>`}
const servers=[['demo-sg','🇸🇬 新加坡 · 192.0.2.10','2 vCPU · 4 GB · 100 GB',[32,68,42],'green'],['demo-jp','🇯🇵 示例地区 · 192.0.2.20','2 vCPU · 4 GB · 100 GB',[24,46,38],'orange'],['demo-us','🇺🇸 美国 · 198.51.100.30','4 vCPU · 8 GB · 200 GB',[58,62,71],''],['demo-nas','⌂ 内网 192.0.2.40','4 vCPU · 16 GB · 4 TB',[18,32,56],'orange']];
